  Material M(string n,Color c,float metalness=0,float smooth=.35f){var s=Shader.Find("Universal Render Pipeline/Lit");if(!s)s=Shader.Find("Standard");var m=new Material(s){name=n,color=c};if(m.HasProperty("_Metallic"))m.SetFloat("_Metallic",metalness);if(m.HasProperty("_Smoothness"))m.SetFloat("_Smoothness",smooth);return m;}
