  void AddInteract(GameObject o,StoreInteractable.ActionType type){var i=o.AddComponent<StoreInteractable>();i.actionType=type;}
  void Terminals(){for(int i=0;i<5;i++){var o=Cube("Restock station",new Vector3(-8+i*4,.8f,8.7f),new Vector3(1.2f,1.4f,.65f),green);var a=o.AddComponent<StoreInteractable>();a.actionType=StoreInteractable.ActionType.Restock;a.stock=12;}
   var order=Cube("Order terminal",new Vector3(-8.7f,1.1f,12.5f),new Vector3(.8f,1.7f,.55f),metal);AddInteract(order,StoreInteractable.ActionType.Order);var up=Cube("Upgrade terminal",new Vector3(8.5f,1.1f,12.5f),new Vector3(.8f,1.7f,.55f),M("Blue terminal",new Color(.15f,.35f,.75f)));AddInteract(up,StoreInteractable.ActionType.Upgrade);}
  void Lighting(){RenderSettings.ambientMode=AmbientMode.Trilight;RenderSettings.ambientSkyColor=new Color(.52f,.58f,.64f);RenderSettings.ambientEquatorColor=new Color(.35f,.37f,.34f);RenderSettings.ambientGroundColor=new Color(.18f,.17f,.15f);var sun=new GameObject("Sun key light").AddComponent<Light>();sun.type=LightType.Directional;sun.intensity=1.05f;sun.color=new Color(1,.91f,.78f);sun.transform.rotation=Quaternion.Euler(48,-28,0);sun.shadows=LightShadows.Soft;}
  void NetworkSetup(){var go=new GameObject("NetworkManager");net=go.AddComponent<NetworkManager>();var t=go.AddComponent<UnityTransport>();net.NetworkConfig=new NetworkConfig{NetworkTransport=t,EnableSceneManagement=false};var p=new GameObject("NetworkPlayerPrefab");p.AddComponent<CharacterController>();p.AddComponent<NetworkObject>();p.AddComponent<NetworkTransform>();p.AddComponent<FirstPersonPlayer>();var body=GameObject.CreatePrimitive(PrimitiveType.Capsule);body.transform.SetParent(p.transform,false);body.transform.localPosition=new Vector3(0,.85f,0);body.transform.localScale=new Vector3(.65f,.85f,.55f);body.GetComponent<Renderer>().material=green;net.NetworkConfig.PlayerPrefab=p;p.SetActive(false);DontDestroyOnLoad(go);}
  IEnumerator Customers(){yield return new WaitForSeconds(1);for(int i=0;i<9;i++){var o=new GameObject("Customer "+(i+1));var a=o.AddComponent<ShopperAI>();a.Init(new Vector3(Random.Range(-8,8),0,Random.Range(-4,5)),M("Clothing",Color.HSVToRGB(Random.value,.45f,.75f)),M("Skin",new Color(Random.Range(.55f,.9f),Random.Range(.36f,.72f),Random.Range(.22f,.55f))));yield return new WaitForSeconds(.3f);}}
  public void Message(string s){message=s;messageTime=3.2f;}
  public void Checkout(){if(shelfStock<=0){Message("No stock left — restock shelves.");return;}int earn=Random.Range(18,43)+reputation*2;money+=earn;shelfStock=Mathf.Max(0,shelfStock-Random.Range(1,4));customersServed++;Message("Checkout complete  +$"+earn);}
  public void CustomerPurchase(){if(shelfStock>0){shelfStock--;money+=Random.Range(3,10);}if(Random.value<.18f)reputation=Mathf.Min(5,reputation+1);}
  void InitGUI(){if(styles)return;title=new GUIStyle(GUI.skin.label){fontSize=20,fontStyle=FontStyle.Bold,normal={textColor=new Color(.85f,1,.9f)}};panel=new GUIStyle(GUI.skin.box);panel.normal.background=Tex(new Color(.025f,.055f,.06f,.94f));text=new GUIStyle(GUI.skin.label){fontSize=18,fontStyle=FontStyle.Bold,normal={textColor=Color.white}};small=new GUIStyle(GUI.skin.label){fontSize=14,normal={textColor=new Color(.72f,.82f,.81f)}};button=new GUIStyle(GUI.skin.button){fontSize=16,fontStyle=FontStyle.Bold,fixedHeight=38};styles=true;}
